function sumImbalanceNumbers(nums) {
  const n = nums.length;
  let total = 0;
  for (let left = 0; left < n; left++) {
    const seen = new Set([nums[left]]);
    let imbalance = 0;
    for (let right = left + 1; right < n; right++) {
      const value = nums[right];
      if (!seen.has(value)) {
        const below = seen.has(value - 1);
        const above = seen.has(value + 1);
        if (!below && !above) {
          imbalance++;
        } else if (below && above) {
          imbalance--;
        }
        seen.add(value);
      }
      total += imbalance;
    }
  }
  return total;
}

