function sumImbalanceNumbers(nums) {
  let total = 0;
  for (let i = 0; i < nums.length; i++) {
    for (let j = i; j < nums.length; j++) {
      const sorted = nums.slice(i, j + 1).sort((a, b) => a - b);
      for (let k = 0; k + 1 < sorted.length; k++) {
        if (sorted[k + 1] - sorted[k] > 1) total++;
      }
    }
  }
  return total;
}

