function generate(rand, size) {
  const n = size === 'large' ? 1000 : 1 + Math.floor(rand() * 9);
  // Sometimes squeeze values into a narrow range so duplicates and neighbours are common.
  const top = rand() < 0.4 ? Math.max(1, Math.floor(n / 3)) : n;
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  return [nums];
}
